const Fastify = require('fastify');
const { AccountModel } = require('./models');
const { authenticateToken } = require('./auth');

const fastify = Fastify();

fastify.register(async function billingRoutes(instance) {
  instance.addHook('preHandler', async (request, reply) => {
    const user = await authenticateToken(request.headers['x-auth-token']);
    if (!user) {
      return reply.status(401).send({ error: 'Unauthorized' });
    }
    request.user = user;
  });

  instance.get('/api/billing/invoices', async (request, reply) => {
    const requestedAccountId = request.query?.accountId;

    // Fall back to user's assigned account if not specified, or ensure requested account matches ownership
    const targetAccountId = requestedAccountId || request.user.accountId;
    if (targetAccountId !== request.user.accountId && !request.user.isSuperAdmin) {
      return reply.status(403).send({ error: 'Forbidden: cannot access billing invoices of another account' });
    }

    const account = await AccountModel.findByPk(targetAccountId);
    if (!account) {
      return reply.status(404).send({ error: 'Account not found' });
    }

    const invoices = await account.getInvoices();
    return reply.send({ accountId: account.id, invoices });
  });
});

fastify.listen({ port: 8093 });
